import numpy as np
import matplotlib.pyplot as plt

# Activation functions
def sigmoid(x):
    return 1 / (1 + np.exp(-x))

def tanh(x):
    return np.tanh(x)  # or (np.exp(x) - np.exp(-x)) / (np.exp(x) + np.exp(-x))

def relu(x):
    return np.maximum(0, x)

def leaky_relu(x, alpha=0.01):
    return np.where(x > 0, x, alpha * x)

def elu(x, alpha=1.0):
    return np.where(x > 0, x, alpha * (np.exp(x) - 1))

def softmax(x):
    exp_x = np.exp(x - np.max(x))  # subtract max for numerical stability
    return exp_x / exp_x.sum()

def gelu(x):
    # Gaussian Error Linear Unit (used in BERT, GPT)
    return 0.5 * x * (1 + np.tanh(np.sqrt(2/np.pi) * (x + 0.044715 * x**3)))

# Derivatives (for backpropagation)
def sigmoid_derivative(x):
    s = sigmoid(x)
    return s * (1 - s)

def tanh_derivative(x):
    return 1 - np.tanh(x)**2

def relu_derivative(x):
    return np.where(x > 0, 1, 0)

# Visualize
x = np.linspace(-5, 5, 1000)

fig, axes = plt.subplots(2, 3, figsize=(15, 10))
functions = [
    ('Sigmoid', sigmoid(x), sigmoid_derivative(x)),
    ('Tanh', tanh(x), tanh_derivative(x)),
    ('ReLU', relu(x), relu_derivative(x)),
    ('Leaky ReLU', leaky_relu(x), np.where(x > 0, 1, 0.01)),
    ('ELU', elu(x), np.where(x > 0, 1, elu(x) + 1)),
    ('GELU', gelu(x), None)  # Derivative is complex
]

for (name, y, dy), ax in zip(functions, axes.flat):
    ax.plot(x, y, 'b-', label=f'{name}', linewidth=2)
    if dy is not None:
        ax.plot(x, dy, 'r--', label=f"{name}'", alpha=0.7)
    ax.axhline(y=0, color='k', linewidth=0.5)
    ax.axvline(x=0, color='k', linewidth=0.5)
    ax.set_title(name)
    ax.legend()
    ax.grid(True, alpha=0.3)

plt.tight_layout()
plt.show()

# Practical usage in a neural network layer
class Layer:
    def __init__(self, input_size, output_size, activation='relu'):
        self.weights = np.random.randn(input_size, output_size) * 0.01
        self.bias = np.zeros((1, output_size))
        self.activation = activation

    def forward(self, X):
        self.z = np.dot(X, self.weights) + self.bias

        if self.activation == 'sigmoid':
            self.a = sigmoid(self.z)
        elif self.activation == 'tanh':
            self.a = tanh(self.z)
        elif self.activation == 'relu':
            self.a = relu(self.z)
        elif self.activation == 'softmax':
            self.a = softmax(self.z)
        else:
            self.a = self.z  # linear

        return self.a
